import{_ as i,o as a,c as n,a4 as l}from"./chunks/framework.B-wJupoK.js";const p="/assets/app_icon.BXgrWyDv.png",e="/assets/image-20250611204754078.DhZLR39g.png",t="/assets/image-20250611204954959.DbFsSlLJ.png",h="/assets/image-20250611205434090.C5wGcfd4.png",k="/assets/image-20250611205737698.f_QIaXQ4.png",r="/assets/image-20250611205822773.CZ54q03I.png",E="/assets/image-20250611205911493.DzQCpVwV.png",d="/assets/image-20250611210253010.CIsAwfzA.png",g="/assets/image-20250611210518776.CMCGCPUR.png",o="/assets/image-20250611210618194.DKHW9QyB.png",c="/assets/image-20250611210727570.GIGNkWMQ.png",y="/assets/image-20250611210745710.szW_icN3.png",b="/assets/image-20250611210802187.bKpngyfL.png",F="/assets/image-20250611221653937.BwIieahd.png",u="/assets/image-20250611210852519.Co8Tb8Og.png",m="/assets/image-20250611211811768.AjWr7Ss_.png",T=JSON.parse('{"title":"我们又来啦 又又上架了一个鸿蒙项目-萤火故事屋","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/我们又来啦  又又上架了一个鸿蒙项目-萤火故事屋/我们又来啦  又又上架了一个鸿蒙项目-萤火故事屋.md","filePath":"鸿蒙开发技巧/我们又来啦  又又上架了一个鸿蒙项目-萤火故事屋/我们又来啦  又又上架了一个鸿蒙项目-萤火故事屋.md","lastUpdated":1749688592000,"__rawMarkdown":"# 我们又来啦 又又上架了一个鸿蒙项目-萤火故事屋\\n\\n## 萤火故事屋介绍\\n\\n![app_icon](assets/app_icon.png)\\n\\n**萤火故事屋** 是[青蓝逐码](https://www.qinglanzhuma.cn/)孵化的一款针对儿童类的鸿蒙元服务，打造全龄段语言娱乐空间，涵盖童话、脑筋急转弯、绕口令、猜谜语四大模块。童话配套生动剧情，脑筋急转弯、谜语设阶梯模式，绕口令丰富多彩。即刻开启思维与语言的趣味之旅！\\n\\n![image-20250611204754078](assets/image-20250611204754078.png)\\n\\n**萤火故事屋**从 4 月 1 号立项，开发时间一个月，预计 5 月 1 号上架。\\n\\n![image-20250611204954959](assets/image-20250611204954959.png)\\n\\n但是一开始萤火故事屋的名字是叫做 **故事大王**，因为故事大王这个名字起初在鸿蒙应用商店中没有出现过，所以我们负责立项的小伙伴打算叫这个名字。后面华为那边因为这个名字太有特点，需要我们提供这个名字的商标，才能允许上架。但是当初我们备案也是拿故事大王去备案、AGC 上的资料也全部都是**故事大王**，所以等于需要重新走一遍备案的流程，这个上架失败的事情，其实主要原因在于我，因为我昨晚把控流程的负责人，当初其实是感觉到这个名字有问题，但是后面因为某些原因没有细究。\\n\\n![image-20250611205434090](assets/image-20250611205434090.png)\\n\\n这个也充分说明懂技术和做产品其实是两码事。需要把握的事项更多，其中，还需要注意的是，萤火故事屋里面引用的一些故事是否会侵权。**假如，我在这里面引用了 大头儿子和小头爸爸的一些故事，会不会侵权呢 🙂**，这个问题留给聪明的评论区的网友\\n\\n![image-20250611205737698](assets/image-20250611205737698.png)\\n\\n---\\n\\n总而言之吧，最后我们重新调整资料，萤火故事屋就顺利上线了。\\n\\n![image-20250611205822773](assets/image-20250611205822773.png)\\n\\n---\\n\\n![image-20250611205911493](assets/image-20250611205911493.png)\\n\\n## 核心开发人员\\n\\n萤火故事屋的核心开发人员也很年轻呀，都是 25 届毕业的小伙伴。其中 1 个已经有几个鸿蒙项目的开发经验来，也是在工作之余抽空来主导项目的开发，另外一个 25 届的小伙伴要稍弱些，但是大部分的基础代码也是他完成了。\\n\\n![image-20250611210253010](assets/image-20250611210253010.png)\\n\\n## 开发的小故事\\n\\n### 开始组团打怪了\\n\\n![image-20250611210518776](assets/image-20250611210518776.png)\\n\\n### 教小伙伴用用 git\\n\\n![image-20250611210618194](assets/image-20250611210618194.png)\\n\\n### 执行力也很强\\n\\n![image-20250611210727570](assets/image-20250611210727570.png)\\n\\n### 初步有成果\\n\\n![image-20250611210745710](assets/image-20250611210745710.png)\\n\\n### 教一下开发规范\\n\\n![image-20250611210802187](assets/image-20250611210802187.png)\\n\\n### 重命名时候的讨论\\n\\n![image-20250611221653937](assets/image-20250611221653937.png)\\n\\n### 成就感最足的时候吧\\n\\n![image-20250611210852519](assets/image-20250611210852519.png)\\n\\n## 🏗️ 架构设计\\n\\n### 模块化架构\\n\\n- **entry 模块**: 主入口模块，包含核心功能\\n- **home 模块**: 首页相关功能\\n- **my 模块**: 个人中心模块\\n- **collect 模块**: 收藏功能模块\\n- **AppScope**: 全局应用范围配置\\n\\n### 目录结构设计\\n\\n```\\nentry/src/main/ets/\\n├── component/     # 通用组件\\n├── views/        # 视图组件\\n├── pages/        # 页面\\n├── utils/        # 工具类\\n├── Data/         # 数据管理\\n├── constants/    # 常量定义\\n└── storywidget/  # 小组件\\n```\\n\\n## 🚀 核心技术亮点\\n\\n### 1. 现代化 UI 组件体系\\n\\n#### AtomicServiceNavigation 导航系统\\n\\n```typescript\\n// Index.ets\\nimport {\\n  AtomicServiceNavigation,\\n  AtomicServiceTabs,\\n  TabBarOptions,\\n  TabBarPosition,\\n} from \\"@kit.ArkUI\\";\\n```\\n\\n- 使用 `AtomicServiceNavigation` 实现现代化导航\\n- 支持路由栈管理 `NavPathStack`\\n- 集成 `AtomicServiceTabs` 底部标签导航\\n\\n#### 自定义 Builder 模式\\n\\n```typescript\\n@Builder\\nnavigationContent() {\\n  Column() {\\n    AtomicServiceTabs({\\n      tabContents: [\\n        () => {\\n          this.tabContent1()\\n        },\\n        () => {\\n          this.tabContent4()\\n        }\\n      ],\\n      tabBarOptionsArray: [\\n        new TabBarOptions($r(\'app.media.icon_shouye\'), \'首页\', $r(\'app.color.bottom_icon\'), \'#ff39a7b5\'),\\n        new TabBarOptions($r(\'app.media.icon_wode\'), \'我的\', $r(\'app.color.bottom_icon\'), \'#ff39a7b5\'),\\n      ],\\n```\\n\\n### 2. 深色模式完整解决方案\\n\\n#### 系统级深色模式支持\\n\\n```typescript\\nimport { ConfigurationConstant } from \\"@kit.AbilityKit\\"\\n@CustomDialog\\nexport struct blackMode {\\n  controller: CustomDialogController\\n  @StorageLink(\'isOn\') isOn:boolean = true\\n  @StorageLink(\'isNormal\') isNormal:boolean = true\\n\\n  setModel() {\\n    const appContext = getContext().getApplicationContext()\\n    if (this.isOn) {\\n      appContext.setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_NOT_SET)\\n    } else {\\n      appContext.setColorMode(this.isNormal ? ConfigurationConstant.ColorMode.COLOR_MODE_LIGHT :\\n      ConfigurationConstant.ColorMode.COLOR_MODE_DARK)\\n    }\\n  }\\n```\\n\\n**技术特点:**\\n\\n- 支持跟随系统模式\\n- 手动切换亮色/暗色模式\\n- 使用 `@StorageLink` 实现全局状态管理\\n- 自定义对话框组件实现设置界面\\n\\n### 3. 沉浸式全屏体验\\n\\n#### 智能全屏管理\\n\\n```typescript\\nimport { window } from \\"@kit.ArkUI\\";\\nimport {\\n  AREA_BOTTOM,\\n  AREA_TOP,\\n  ENTRY_ABILITY_CONTEXT,\\n} from \\"../constants/Index\\";\\n\\nclass FullScreen {\\n  async enable() {\\n    const ctx = AppStorage.get<Context>(ENTRY_ABILITY_CONTEXT);\\n    let windowClass = await window.getLastWindow(ctx!);\\n    windowClass.setWindowLayoutFullScreen(true);\\n\\n    //保证安全区域\\n    const area = windowClass.getWindowAvoidArea(\\n      window.AvoidAreaType.TYPE_SYSTEM\\n    );\\n    AppStorage.setOrCreate(AREA_TOP, px2vp(area.topRect.height));\\n\\n    const area2 = windowClass.getWindowAvoidArea(\\n      window.AvoidAreaType.TYPE_NAVIGATION_INDICATOR\\n    );\\n    AppStorage.setOrCreate(AREA_BOTTOM, px2vp(area2.bottomRect.height));\\n  }\\n}\\n```\\n\\n**技术亮点:**\\n\\n- 自动计算安全区域避让\\n- 状态栏和导航栏高度适配\\n- 单例模式封装全屏管理\\n\\n### 4. 网络请求架构\\n\\n#### 基于 Axios 的 HTTP 封装\\n\\n```typescript\\nimport axios, {\\n  AxiosError,\\n  AxiosRequestConfig,\\n  AxiosResponse,\\n  InternalAxiosRequestConfig,\\n} from \\"@ohos/axios\\";\\n\\nexport const instance = axios.create({\\n  baseURL: \\"\\",\\n});\\n\\n// 添加请求拦截器\\ninstance.interceptors.request.use(\\n  (config: InternalAxiosRequestConfig) => {\\n    \\"Content-Type: application/x-www-form-urlencoded\\";\\n    return config;\\n  },\\n  (error: AxiosError) => {\\n    return Promise.reject(error);\\n  }\\n);\\n\\n// 响应拦截器\\ninstance.interceptors.response.use(\\n  (response: AxiosResponse) => {\\n    return response.data;\\n  },\\n  (error: AxiosError) => {\\n    return Promise.reject(error);\\n  }\\n);\\n\\nclass Http {\\n  request<T, R = null>(config: AxiosRequestConfig) {\\n    type IAxiosResponse = AxiosResponse<T>;\\n    return instance<T, IAxiosResponse, R>(config).then((res) => {\\n      return Promise.resolve(res as T);\\n    });\\n  }\\n}\\n```\\n\\n**特色功能:**\\n\\n- TypeScript 泛型支持\\n- 请求/响应拦截器\\n- 统一错误处理\\n- 链式调用 API\\n\\n### 5. 广告集成系统\\n\\n#### 原生广告组件\\n\\n```typescript\\nimport { advertising } from \\"@kit.AdsKit\\";\\n\\nexport class NativeAdUtil {\\n  private ads: Array<advertising.Advertisement> = [];\\n  private context: common.UIAbilityContext = getContext(\\n    this\\n  ) as common.UIAbilityContext;\\n\\n  requestAd() {\\n    const adDisplayOptions: advertising.AdDisplayOptions = {\\n      mute: false,\\n    };\\n    const nativeVideoAdReqParams: advertising.AdRequestParams = {\\n      adId: \\"g22kxp6lfs\\",\\n      adType: 3,\\n      adCount: 1,\\n      enableDirectReturnVideoAd: true,\\n    };\\n\\n    const adLoaderListener: advertising.AdLoadListener = {\\n      onAdLoadFailure: (errorCode: number, errorMsg: string) => {\\n        hilog.error(\\n          0x0000,\\n          \\"testTag\\",\\n          \\"%{public}s\\",\\n          `Failed to request ad, message: ${errorMsg}, error code: ${errorCode}`\\n        );\\n      },\\n      onAdLoadSuccess: (ads: Array<advertising.Advertisement>) => {\\n        emitter.emit(\\"NativeAdPage\\", {\\n          data: { ads: ads, adDisplayOptions: adDisplayOptions },\\n        });\\n      },\\n    };\\n  }\\n}\\n```\\n\\n**广告特性:**\\n\\n- 支持原生广告和插屏广告\\n- 事件驱动的广告加载\\n- 完整的错误处理机制\\n- 广告内容分级控制\\n\\n### 6. 状态管理体系\\n\\n#### 多层级状态管理\\n\\n```typescript\\n@StorageProp(AREA_TOP)\\nsafeTop: number = 0\\n@StorageProp(AREA_BOTTOM)\\nsafeBottom: number = 0\\n@StorageProp(\'isOn\') isOn: boolean = true\\n@StorageProp(\'isNormal\') isNormal: boolean = true\\n@Provide(\\"pageStack\\")\\npageStack: NavPathStack = new NavPathStack()\\n```\\n\\n**状态管理策略:**\\n\\n- `@StorageProp`: 全局持久化状态\\n- `@Provide/@Consume`: 跨组件状态传递\\n- `@State`: 组件内部状态\\n- `@Watch`: 状态变化监听\\n\\n### 7. 智能搜索系统\\n\\n#### 动态搜索提示\\n\\n```typescript\\ntitleArr() {\\n  const resProverbsAll = this.proverbsAll.map((item: ProverbsDetail) => {\\n    return item.text\\n  })\\n  const resRiddlesArr = this.riddlesArr.map((item: RiddlesObj) => {\\n    return item.question\\n  })\\n  const resStoryDetailsAll = this.storyDetailsAll.map((item: StoryDetailsObj) => {\\n    return item.title\\n  })\\n  const resTopTabsRiddleArr = this.topTabsRiddleArr.map((item: TopTabsRiddle) => {\\n    return item.title\\n  })\\n  this.TitleArr.push(...resProverbsAll, ...resRiddlesArr, ...resStoryDetailsAll, ...resTopTabsRiddleArr)\\n}\\n\\nTitle() {\\n  const res = Math.floor(Math.random() * this.TitleArr.length);\\n  this.title = this.TitleArr[res]\\n}\\n```\\n\\n**搜索特色:**\\n\\n- 多数据源聚合搜索\\n- 随机搜索提示轮播\\n- 定时器控制搜索框动效\\n\\n### 8. 性能优化技巧\\n\\n#### 视图可见性优化\\n\\n```typescript\\n.onVisibleAreaChange([0, 1], (isVisible) => {\\n  if (isVisible) {\\n    const res = setInterval(() => {\\n      this.Title()\\n      console.log(\'你是猪\')\\n    }, 3000)\\n    this.setIntervalID = res\\n  } else {\\n    clearInterval(this.setIntervalID)\\n  }\\n})\\n```\\n\\n**优化策略:**\\n\\n- 基于可见性的定时器管理\\n- 避免不必要的后台计算\\n- 内存泄漏预防\\n\\n### 9. 趣味交互设计\\n\\n#### 随机励志语录弹窗\\n\\n```typescript\\n@State messageList: string[] = [\\n  \'成长不是一蹴而就，每一次错误都是成长的台阶，勇于犯错，才能更快抵达成熟的彼岸。\',\\n  \'学习如同登山，每一步攀登都可能艰辛，但每一次登高都会让你看到更美的风景。\',\\n  // ... 更多励志语录\\n]\\n\\n.onClick(() => {\\n  this.handlePopup = true\\n  if(this.handlePopup){\\n    this.Message = this.messageList[Math.floor(Math.random() * this.messageList.length)]\\n  }\\n})\\n```\\n\\n**交互亮点:**\\n\\n- 随机励志语录系统\\n- 浮动卡片设计\\n- 阴影和圆角现代化 UI\\n\\n## 🛠️ 编程技巧总结\\n\\n### 1. ArkTS 最佳实践\\n\\n- 严格的类型定义\\n- 泛型编程应用\\n- 接口定义规范\\n\\n### 2. 组件化设计模式\\n\\n- 高内聚低耦合组件\\n- 可复用 UI 组件库\\n- 统一的组件接口\\n\\n### 3. 异步编程处理\\n\\n- Promise 链式调用\\n- async/await 语法\\n- 错误边界处理\\n\\n### 4. 内存管理优化\\n\\n- 定时器生命周期管理\\n- 事件监听器清理\\n- 组件销毁时的资源释放\\n\\n### 5. 用户体验优化\\n\\n- 加载状态管理\\n- 错误状态友好提示\\n- 流畅的页面转场动效\\n\\n## 📱 设备适配特性\\n\\n- **多设备支持**: 手机和平板适配\\n- **安全区域适配**: 全面屏设备支持\\n- **响应式布局**: 不同屏幕尺寸自适应\\n- **深色模式**: 系统级主题切换\\n\\n## 总结\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250611211811768](assets/image-20250611211811768.png)\\n"}'),C={name:"鸿蒙开发技巧/我们又来啦  又又上架了一个鸿蒙项目-萤火故事屋/我们又来啦  又又上架了一个鸿蒙项目-萤火故事屋.md"};function A(B,s,D,v,_,q){return a(),n("div",null,[...s[0]||(s[0]=[l("",103)])])}const f=i(C,[["render",A]]);export{T as __pageData,f as default};
